  "confidence": 0.8,
  "anomalies": [
    {
      "category": "footprint_mismatch",
      "components": ["U3"],
      "pins": ["U3.2", "U3.3"],
      "nets": ["TACH", "POT"],
      "observed": "U3 (ATtiny13V-10S) is drawn with pin 2 as PB4 connected to the TACH net and pin 3 as PB3 connected to the POT net. U2 (ATtiny45-20P) uses the opposite, datasheet-correct mapping: pin 2 PB3 on POT and pin 3 PB4 on TACH.",
      "expected": "The ATtiny13V and ATtiny45 8-pin footprints should be pin-compatible: physical pin 2 is PB3 and physical pin 3 is PB4. If both MCU footprints are intended as alternatives, U3 pin 2 should carry PB3/POT and U3 pin 3 should carry PB4/TACH, matching U2 and the part datasheet.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "U3 ATtiny13V-10S: 3 PB3 POT, 2 PB4 TACH (fan_controller.kicad_sch, right tile)"
        },
        {
          "source": "schematic",
          "quote": "U2 ATtiny45-20P: 2 PB3 POT, 3 PB4 TACH (fan_controller.kicad_sch, right tile)"
        },
        {
          "source": "spec",
          "quote": "an ATtiny-driven fan controller"
        }
      ],
      "impact": "If the SMD MCU footprint U3 is populated, the pot and tachometer signals are swapped relative to the THT MCU footprint and likely firmware expectations. Fan speed input and tachometer feedback would be read from the wrong pins, causing incorrect fan control/monitoring.",
      "confidence": 0.8
    }
  ],
  "summary": "Anomaly detected: the ATtiny13V SMD MCU footprint has PB3/PB4 (POT/TACH) swapped relative to the ATtiny45 footprint and the standard ATtiny pinout, so the board would behave differently depending on which MCU footprint is populated."
}

